import { useNavigate } from "react-router-dom";
import Navbar from "../components/Navbar";
import { useState } from "react";
import { API } from "../api/api";

export default function Home() {
  const nav = useNavigate();

  const [showPolls, setShowPolls] = useState(false);
  const [polls, setPolls] = useState([]);
const [category, setCategory] = useState("all");
  const [showSurveys, setShowSurveys] = useState(false);
  const [surveys, setSurveys] = useState([]);

  const fetchPolls = async () => {
    try {
      const res = await API.get("/polls");
      setPolls(res.data || []);
    } catch {
      setPolls([]);
    }
  };

  const fetchSurveys = async () => {
    try {
      const res = await API.get("/surveys");
      setSurveys(res.data || []);
    } catch {
      setSurveys([]);
    }
  };

  return (
    <>
      <Navbar />

      <style>{`
        *{
          margin:0;
          padding:0;
          box-sizing:border-box;
          font-family:Arial, sans-serif;
        }

        body{
          background:#0b1220;
        }

        .home-container{
          min-height:100vh;
          padding:40px;
          color:white;
          background: radial-gradient(circle at top,#1e3a8a,#0b1220 60%);
        }

        /* HERO */
        .hero{
          text-align:center;
          margin-bottom:60px;
        }

        .hero h1{
          font-size:38px;
          font-weight:800;
          letter-spacing:1px;
        }

        /* CONTAINER */
        .container{
          display:flex;
          justify-content:center;
          gap:40px;
          flex-wrap:wrap;
        }

        /* ⭐ MODERN CARD */
        .card{
          width:400px;
          min-height:340px;
          border-radius:18px;
          overflow:hidden;

          background:#111827;
          border:1px solid rgba(255,255,255,0.08);

          box-shadow:0 10px 30px rgba(0,0,0,0.4);

          transition:0.3s;
          position:relative;
        }

        .card:hover{
          transform:translateY(-8px);
          box-shadow:0 20px 50px rgba(0,0,0,0.6);
        }

        /* TOP ACCENT BAR */
        .bar{
          height:5px;
          width:100%;
        }

        .poll-bar{
          background:linear-gradient(90deg,#22c55e,#16a34a);
        }

        .survey-bar{
          background:linear-gradient(90deg,#3b82f6,#2563eb);
        }

        /* HEADER INSIDE CARD */
        .card-header{
          display:flex;
          align-items:center;
          gap:10px;
          padding:20px 20px 10px;
        }

        .icon{
          font-size:30px;
        }

        .title{
          font-size:20px;
          font-weight:700;
        }

        /* BODY */
        .card-body{
          padding:0 20px 20px;
        }

        .start-text{
          font-size:24px;
          font-weight:700;
          margin-top:10px;
          cursor:pointer;
          color:#22c55e;
        }

        .start-text:hover{
          text-decoration:underline;
        }

        p{
          font-size:13px;
          color:#9ca3af;
          margin:10px 0 15px;
        }

        /* BUTTON */
        .plus-btn{
          width:65px;
          height:65px;
          border:none;
          border-radius:50%;
          font-size:30px;
          cursor:pointer;
          color:white;
          background:linear-gradient(135deg,#22c55e,#16a34a);
          margin-top:10px;
          transition:0.3s;
        }

        .plus-btn:hover{
          transform:rotate(90deg) scale(1.1);
        }

        /* LIST ITEMS */
        .poll-item,
        .survey-item{
          padding:10px;
          margin:8px 0;
          background:#1f2937;
          border-radius:10px;
          cursor:pointer;
          font-size:14px;
          transition:0.2s;
          border:1px solid rgba(255,255,255,0.05);
        }

        .poll-item:hover,
        .survey-item:hover{
          background:#374151;
          transform:scale(1.02);
        }

        /* EMPTY STATE */
        .empty-box{
          margin-top:25px;
          color:#9ca3af;
        }

        .empty-box h3{
          font-size:18px;
          color:white;
          margin-bottom:5px;
        }

        .back-btn{
          margin-top:15px;
          padding:8px 14px;
          border:none;
          border-radius:8px;
          cursor:pointer;
          background:#e5e7eb;
          font-size:13px;
        }
      `}</style>
<div className="category-bar">
  {["all", "student", "teacher", "general"].map(cat => (
    <button
      key={cat}
      onClick={() => setCategory(cat)}
      className={category === cat ? "active-cat" : ""}
    >
      {cat.toUpperCase()}
    </button>
  ))}
</div>
      <div className="home-container">

        {/* HERO */}
        <div className="hero">
          <h1>Survey Hub 🚀</h1>
        </div>

        <div className="container">

          {/* POLL CARD */}
          <div className="card">

            <div className="bar poll-bar"></div>

            <div className="card-header">
              <div className="icon">📊</div>
              <div className="title">Polls</div>
            </div>

            <div className="card-body">

              {!showPolls ? (
                <>
                  <div
                    className="start-text"
                    onClick={() => {
                      setShowPolls(true);
                      fetchPolls();
                    }}
                  >
                    START POLL
                  </div>

                  <p>Create and manage quick polls</p>

                  <button
                    className="plus-btn"
                    onClick={() => nav("/create-poll")}
                  >
                    +
                  </button>
                </>
              ) : (
                <>
                  <h3>Old Polls</h3>

                  {polls.filter(p => p.title && p.title.trim()).length === 0 ? (
                    <div className="empty-box">
                      <h3>No polls yet</h3>
                      <p>Create your first poll</p>
                    </div>
                  ) : (
                    polls
                      .filter(p => p.title && p.title.trim())
                      .map(p => (
                        <div
                          key={p._id}
                          className="poll-item"
                          onClick={() => nav(`/poll/${p._id}`)}
                        >
                          {p.title}
                        </div>
                      ))
                  )}

                  <button className="back-btn" onClick={() => setShowPolls(false)}>
                    ← Back
                  </button>
                </>
              )}

            </div>
          </div>

          {/* SURVEY CARD */}
          <div className="card">

            <div className="bar survey-bar"></div>

            <div className="card-header">
              <div className="icon">📝</div>
              <div className="title">Surveys</div>
            </div>

            <div className="card-body">

              {!showSurveys ? (
                <>
                  <div
                    className="start-text"
                    style={{ color: "#3b82f6" }}
                    onClick={() => {
                      setShowSurveys(true);
                      fetchSurveys();
                    }}
                  >
                    START SURVEY
                  </div>

                  <p>Create detailed feedback surveys</p>

                  <button
                    className="plus-btn"
                    style={{ background: "linear-gradient(135deg,#3b82f6,#2563eb)" }}
                    onClick={() => nav("/create-survey")}
                  >
                    +
                  </button>
                </>
              ) : (
                <>
                  <h3>Old Surveys</h3>

                  {surveys.filter(s => s.title && s.title.trim()).length === 0 ? (
                    <div className="empty-box">
                      <h3>No surveys yet</h3>
                      <p>Create your first survey</p>
                    </div>
                  ) : (
                    surveys
                      .filter(s => s.title && s.title.trim())
                      .map(s => (
                        <div
                          key={s._id}
                          className="survey-item"
                          onClick={() => nav(`/survey/${s._id}`)}
                        >
                          {s.title}
                        </div>
                      ))
                  )}

                  <button className="back-btn" onClick={() => setShowSurveys(false)}>
                    ← Back
                  </button>
                </>
              )}

            </div>
          </div>

        </div>
      </div>
    </>
  );
}
